const defaults=()=>({version:1,theme:'evjf',name:'Il nostro addio al nubilato in Puglia',people:6,start:'',days:3,arrival:'Bari',budget:400,pace:'slow',transport:'driving',interests:['beach','food','party'],zone:null,plan:[],members:Array.from({length:6},(_,i)=>'Persona '+(i+1)),expenses:[],notes:[],splitLink:''});
let state=defaults(),view='prepare',day=0,map,layer,photoFile=null,weatherByZone={},weatherSequence=0;
function validate(s){const safeId=x=>typeof x==='string'&&/^[a-zA-Z0-9-]{1,100}$/.test(x);if(!s||s.version!==1||!themes.some(t=>t[0]===s.theme)||typeof s.name!=='string'||s.name.length>80||!Number.isInteger(s.people)||s.people<2||s.people>40||!Number.isInteger(s.days)||s.days<1||s.days>14||!Array.isArray(s.plan)||s.plan.length>14||!Array.isArray(s.members)||s.members.length!==s.people||s.members.some(x=>typeof x!=='string'||!x.trim()||x.length>60)||new Set(s.members).size!==s.people)throw Error('Copia non riconosciuta');if(typeof s.start!=='string'||(s.start&&!/^\d{4}-\d{2}-\d{2}$/.test(s.start))||!['Bari','Brindisi','Foggia','Libre'].includes(s.arrival)||!['slow','active'].includes(s.pace)||!['driving','transit'].includes(s.transport)||!Number.isFinite(s.budget)||s.budget<0||s.budget>100000||!Array.isArray(s.interests)||s.interests.some(x=>!kinds[x])||!Array.isArray(s.expenses)||!Array.isArray(s.notes)||s.notes.length>1000||s.expenses.length>2000)throw Error('Dati non validi');for(const d of s.plan){if(!Array.isArray(d)||d.length>50)throw Error('Programma non valido');for(const p of d){if(!safeId(p.uid)||typeof p.name!=='string'||p.name.length>200||typeof p.desc!=='string'||p.desc.length>4000||typeof p.time!=='string'||(p.lat!=null&&(!Number.isFinite(p.lat)||Math.abs(p.lat)>90))||(p.lon!=null&&(!Number.isFinite(p.lon)||Math.abs(p.lon)>180)))throw Error('Tappa non valida')}}for(const e of s.expenses){if(!safeId(e.id)||typeof e.title!=='string'||!Number.isInteger(e.cents)||e.cents<1||e.cents>10000000||!s.members.includes(e.payer)||!Array.isArray(e.who)||!e.who.length||e.who.some(n=>!s.members.includes(n))||new Set(e.who).size!==e.who.length)throw Error('Spesa non valida')}for(const n of s.notes){if(!safeId(n.id)||typeof n.text!=='string'||n.text.length>4000||!['private','group'].includes(n.privacy)||!Number.isInteger(n.day)||n.day< -1||n.day>=s.days)throw Error('Nota non valida')}if(s.splitLink&&!validSplit(s.splitLink))throw Error('Link del gruppo non valido');return s}
try{const saved=localStorage.getItem('aracne-puglia-v1');if(saved)state=validate(JSON.parse(saved))}catch{setTimeout(()=>toast('Impossibile caricare il salvataggio locale. Potete importare una copia.'),400)}
function save(){try{localStorage.setItem('aracne-puglia-v1',JSON.stringify(state))}catch{toast('Salvataggio locale non disponibile. Esportate il viaggio.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function show(v){view=v;$$('.view').forEach(e=>e.classList.toggle('active',e.id===v));$$('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===v));if(v==='map')setTimeout(drawMap,40);if(v==='plan')renderPlan();if(v==='budget')renderBudget();if(v==='notes')renderNotes();window.scrollTo({top:0,behavior:'smooth'})}
function dialog(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').showModal()}
$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
$$('nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();show('prepare')};
function fillForm(){$('#tripName').value=state.name;$('#people').value=state.people;$('#start').value=state.start;$('#start').min=today();$('#days').innerHTML=Array.from({length:14},(_,i)=>`<option value="${i+1}">${i+1} ${i?'giorni':'giorno'}</option>`).join('');$('#days').value=state.days;$('#arrival').value=state.arrival;$('#budgetTarget').value=state.budget;$('#pace').value=state.pace;$('#transport').value=state.transport;renderChoices()}
function renderChoices(){$('#themes').innerHTML=themes.map(t=>`<button type="button" class="theme ${state.theme===t[0]?'selected':''}" data-theme="${t[0]}" aria-pressed="${state.theme===t[0]}"><b aria-hidden="true">${t[1]}</b>${t[2]}</button>`).join('');$('#interests').innerHTML=Object.entries(kinds).map(([k,n])=>`<button type="button" class="chip ${state.interests.includes(k)?'selected':''}" data-interest="${k}" aria-pressed="${state.interests.includes(k)}">${n}</button>`).join('');$$('[data-theme]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.theme;save();renderChoices()});$$('[data-interest]').forEach(b=>b.onclick=()=>{const k=b.dataset.interest;state.interests=state.interests.includes(k)?state.interests.filter(x=>x!==k):[...state.interests,k];save();renderChoices()})}
function syncForm(){const count=Number($('#people').value),duration=Number($('#days').value);if(state.expenses.length&&count!==state.people){toast('Il gruppo ha già delle spese: mantenete il numero di persone per preservare i conti.');$('#people').value=state.people;return false}if(state.plan.length>duration&&state.plan.slice(duration).some(x=>x.length)){if(!confirm('Ridurre la durata eliminerà le tappe degli ultimi giorni. Continuare?'))return false}Object.assign(state,{name:$('#tripName').value.trim(),people:count,start:$('#start').value,days:duration,arrival:$('#arrival').value,budget:Number($('#budgetTarget').value)||0,pace:$('#pace').value,transport:$('#transport').value});while(state.members.length<count)state.members.push('Persona '+(state.members.length+1));state.members=state.members.slice(0,count);state.plan=state.plan.slice(0,duration);state.notes.forEach(n=>{if(n.day>=duration)n.day=-1});day=Math.min(day,duration-1);save();return true}
$('#tripForm').onsubmit=async e=>{e.preventDefault();if(!syncForm())return;if(!state.interests.length){toast('Scegliete almeno un interesse.');return}$('#recommendations').hidden=false;weatherByZone={};renderZones();$('#recommendations').scrollIntoView({behavior:'smooth',block:'start'});await weather()};
function score(z){let n=state.interests.filter(t=>z.tags.includes(t)).length*10;if(z.arrival===state.arrival)n+=state.days<4?10:4;if(['evjf','evg','friends'].includes(state.theme)&&['bari','salento'].includes(z.id)&&state.interests.includes('party'))n+=3;if(state.theme==='family'&&z.tags.includes('nature'))n+=3;const w=weatherByZone[z.id];if(w)n+=w.bonus;return n}
function renderZones(){const sorted=[...zones].sort((a,b)=>score(b)-score(a));$('#zoneCards').innerHTML=sorted.map((z,i)=>{const w=weatherByZone[z.id];return `<article class="zoneCard"><div><span class="eyebrow">${i===0?'LA NOSTRA PRIMA IDEA':esc(z.base)}</span><h3>${esc(z.name)}</h3><p>${esc(z.desc)}</p><span class="tag">${state.interests.filter(t=>z.tags.includes(t)).map(t=>kinds[t]).join(' · ')||'Un’altra atmosfera da esplorare'}</span>${w?`<p class="weather">${w.temp} °C max. media · ${w.rain} % pioggia max. · vento max. ${w.wind} km/h<br>${w.count}/${state.days} giorni couverts · ${esc(z.base)} / punto rappresentativo</p>`:''}</div><button class="primary" data-zone="${z.id}">Scegli questa zona</button></article>`}).join('');$$('[data-zone]').forEach(b=>b.onclick=()=>generate(b.dataset.zone))}
async function weather(){const seq=++weatherSequence;const diff=(new Date(state.start+'T00:00:00Z')-new Date(today()+'T00:00:00Z'))/86400000;const node=$('#weatherStatus');if(diff<0||diff>15){node.textContent='Date fuori dalla finestra delle previsioni. Le zone sono ordinate per interessi e arrivo, senza vantaggi meteo presunti. Per spiaggia e serate verificate le aperture stagionali; confrontate il meteo vicino alla partenza.';return}node.textContent='Confronto del meteo nelle sei zone…';try{const q=new URLSearchParams({latitude:zones.map(z=>z.lat).join(','),longitude:zones.map(z=>z.lon).join(','),daily:'temperature_2m_max,precipitation_probability_max,wind_speed_10m_max',timezone:'Europe/Rome',forecast_days:'16'});const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),12000);let res;try{res=await fetch('https://api.open-meteo.com/v1/forecast?'+q,{signal:controller.signal})}finally{clearTimeout(timeout)}if(!res.ok)throw Error();const data=await res.json();if(seq!==weatherSequence)return;if(!Array.isArray(data)||data.length!==zones.length)throw Error();const result={};data.forEach((d,i)=>{const indexes=d.daily.time.map((t,j)=>({t,j})).filter(v=>v.t>=state.start&&v.t<dateAt(state.days));const valid=indexes.filter(({j})=>Number.isFinite(d.daily.temperature_2m_max[j])&&Number.isFinite(d.daily.precipitation_probability_max[j])&&Number.isFinite(d.daily.wind_speed_10m_max[j]));if(!valid.length)return;let temp=Math.round(valid.reduce((a,v)=>a+d.daily.temperature_2m_max[v.j],0)/valid.length),rain=Math.max(...valid.map(v=>d.daily.precipitation_probability_max[v.j])),wind=Math.round(Math.max(...valid.map(v=>d.daily.wind_speed_10m_max[v.j])));result[zones[i].id]={temp,rain,wind,count:valid.length,bonus:(100-rain)/15-Math.max(0,wind-20)/5+(state.interests.includes('beach')?Math.max(-5,5-Math.abs(temp-26)):0)}});weatherByZone=result;node.textContent=`Previsioni Open-Meteo consultate alle ${new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}. Pioggia, vento e temperatura completano i vostri interessi. ${diff+state.days>16?'Il soggiorno supera la finestra: confronto parziale. ':''}Sono punti rappresentativi, non una garanzia per ogni spiaggia; verificate le condizioni del mare.`;renderZones()}catch{if(seq===weatherSequence){weatherByZone={};node.textContent='Meteo momentaneamente non disponibile. La classifica usa solo interessi e arrivo; nessuna previsione viene inventata.';renderZones()}}}
function dateAt(d){if(!state.start)return '';let dt=new Date(state.start+'T12:00:00Z');dt.setUTCDate(dt.getUTCDate()+d);return dt.toISOString().slice(0,10)}
function dayLabel(d){const t=dateAt(d);return 'Giorno '+(d+1)+(t?' · '+new Date(t+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'short'}):'')}
function distance(a,b){const rad=x=>x*Math.PI/180;const x=rad(b.lat-a.lat),y=rad(b.lon-a.lon);return 6371*2*Math.asin(Math.sqrt(Math.sin(x/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(y/2)**2))}
function generate(zone){if(state.plan.some(d=>d.length)&&!confirm('Sostituire il programma con una nuova proposta? Note e spese saranno conservate.'))return;state.zone=zone;const z=zones.find(x=>x.id===zone);let pool=places.filter(p=>p.zone===zone&&p.name!=='Isole Tremiti').sort((a,b)=>b.tags.filter(t=>state.interests.includes(t)).length-a.tags.filter(t=>state.interests.includes(t)).length);const limit=state.pace==='slow'?2:3;state.plan=[];for(let d=0;d<state.days;d++){if(!pool.length){state.plan.push([{uid:uid(),name:'Giornata libera a '+z.base,desc:'Lasciate tempo ai vostri desideri, oppure aggiungete un’attività sulla mappa.',time:'10:00',lat:null,lon:null}]);continue}let first=pool.shift(),chosen=[first];pool.sort((a,b)=>distance(first,a)-distance(first,b));while(chosen.length<limit&&pool.length&&distance(first,pool[0])<(state.transport==='transit'?25:65))chosen.push(pool.shift());state.plan.push(chosen.map((p,i)=>({...p,uid:uid(),time:['10:00','15:00','18:00'][i],desc:p.desc+(p.tags.includes('party')&&state.interests.includes('party')?' Per la serata, cercate un locale aperto nelle vostre date e organizzate il rientro.':'')})))}day=0;save();show('plan');toast('La prima proposta è pronta. Potete modificare tutto.')}
function allSteps(){return state.plan.flat()}
function renderPlan(){$('#planTitle').textContent=state.name;$('#planSummary').innerHTML=`<p>${state.people} persone · ${state.days} giorni · ${themes.find(t=>t[0]===state.theme)[2]}${state.zone?' · '+esc(zones.find(z=>z.id===state.zone)?.name||''):''}</p><p class="notice">${state.transport==='transit'?'Gli orari di autobus e treni non sono verificati. Controllate ogni collegamento prima di prenotare.':'Orari e tempi liberi proposti: adattateli alle prenotazioni e ai tempi di viaggio.'} ${state.budget?'Budget indicativo: '+money(state.budget*100)+' / persona, senza stime dei prezzi delle attività.':''}</p>`;$('#dayTabs').innerHTML=Array.from({length:state.days},(_,i)=>`<button class="${day===i?'active':''}" data-day="${i}">${esc(dayLabel(i))}</button>`).join('');$$('[data-day]').forEach(b=>b.onclick=()=>{day=Number(b.dataset.day);renderPlan()});const arr=state.plan[day]||[];$('#itinerary').innerHTML=arr.length?arr.map((p,i)=>`<article class="step"><span class="number">${i+1}</span><div class="stepContent"><span class="eyebrow">${esc(p.time)||'ORARIO LIBERO'}</span><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><div class="actions"><button class="mini" data-edit="${esc(p.uid)}">Modifica</button><button class="mini" data-up="${i}" ${i===0?'disabled':''} aria-label="Sposta su ${esc(p.name)}">↑</button><button class="mini" data-down="${i}" ${i===arr.length-1?'disabled':''} aria-label="Sposta giù ${esc(p.name)}">↓</button><button class="mini" data-remove="${i}" aria-label="Rimuovi ${esc(p.name)}">Rimuovi</button>${Number.isFinite(p.lat)?`<a class="mini" href="${waze(p)}" target="_blank" rel="noopener">Waze</a>`:''}</div></div></article>`).join(''):'<div class="empty">Questa giornata è vostra.<br>Aggiungete luoghi dalla mappa o una tappa libera.</div>';$$('[data-edit]').forEach(b=>b.onclick=()=>editStep(b.dataset.edit));$$('[data-up]').forEach(b=>b.onclick=()=>move(Number(b.dataset.up),-1));$$('[data-down]').forEach(b=>b.onclick=()=>move(Number(b.dataset.down),1));$$('[data-remove]').forEach(b=>b.onclick=()=>{arr.splice(Number(b.dataset.remove),1);save();renderPlan()});const route=arr.filter(p=>Number.isFinite(p.lat));if(state.transport==='transit'&&route.length>1){$('#routeActions').innerHTML=route.slice(1).map((p,i)=>`<a class="secondary" href="${mapsUrl([route[i],p])}" target="_blank" rel="noopener">Collegamento ${i+1} · Google Maps</a>`).join('');return}$('#routeActions').innerHTML=route.length?`<a class="primary" href="${mapsUrl(route)}" target="_blank" rel="noopener">Percorso del giorno · Google Maps</a>${route.length>5?'<p class="small">Sono incluse le prime cinque tappe. Per le successive aprite ogni tappa separatamente.</p>':''}`:''}
function move(i,delta){const arr=state.plan[day];[arr[i],arr[i+delta]]=[arr[i+delta],arr[i]];save();renderPlan()}
function mapsUrl(arr){arr=arr.slice(0,5);const q=new URLSearchParams({api:'1',destination:arr.at(-1).lat+','+arr.at(-1).lon,travelmode:state.transport});if(arr.length>1)q.set('origin',arr[0].lat+','+arr[0].lon);if(arr.length>2&&state.transport!=='transit')q.set('waypoints',arr.slice(1,-1).map(p=>p.lat+','+p.lon).join('|'));return 'https://www.google.com/maps/dir/?'+q}
function waze(p){return 'https://www.waze.com/ul?'+new URLSearchParams({ll:p.lat+','+p.lon,navigate:'yes'})}
function editStep(id){const old=(state.plan[day]||[]).find(p=>p.uid===id);dialog(old?'Modifica la tappa':'Una tappa tutta vostra',`<form id="stepForm"><label>Nome<input id="stepName" maxlength="200" required value="${esc(old?.name||'')}"></label><div class="grid2"><label>Orario<input id="stepTime" type="time" value="${esc(old?.time||'10:00')}"></label><label>Giorno<select id="stepDay">${Array.from({length:state.days},(_,i)=>`<option value="${i}" ${i===day?'selected':''}>${esc(dayLabel(i))}</option>`).join('')}</select></label></div><label>La vostra idea / indirizzo<textarea id="stepDesc" rows="3" maxlength="4000">${esc(old?.desc||'')}</textarea></label><div class="grid2"><label>Latitudine (facoltativa)<input id="stepLat" type="number" step="any" min="-90" max="90" value="${old?.lat??''}"></label><label>Longitudine (facoltativa)<input id="stepLon" type="number" step="any" min="-180" max="180" value="${old?.lon??''}"></label></div><p class="small">Senza coordinate, la tappa appare nel programma ma non sulla mappa.</p><button class="primary">Salva la tappa</button></form>`);$('#stepForm').onsubmit=e=>{e.preventDefault();if(Boolean($('#stepLat').value)!==Boolean($('#stepLon').value)){toast('Inserite entrambe le coordinate oppure lasciatele vuote.');return}const target=Number($('#stepDay').value);const p={...(old||{}),uid:old?.uid||uid(),name:$('#stepName').value.trim(),desc:$('#stepDesc').value,time:$('#stepTime').value,lat:$('#stepLat').value===''?null:Number($('#stepLat').value),lon:$('#stepLon').value===''?null:Number($('#stepLon').value)};if(old)state.plan[day]=state.plan[day].filter(x=>x.uid!==id);while(state.plan.length<state.days)state.plan.push([]);state.plan[target].push(p);day=target;save();$('#modal').close();renderPlan()}}
$('#addManual').onclick=()=>editStep();$('#explore').onclick=()=>show('map');
$('#zoneFilter').innerHTML+=zones.map(z=>`<option value="${z.id}">${esc(z.name)}</option>`).join('');$('#zoneFilter').onchange=drawMap;$('#search').oninput=drawMap;
function filtered(){const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const q=norm($('#search').value.trim());return places.filter(p=>($('#zoneFilter').value==='all'||p.zone===$('#zoneFilter').value)&&norm([p.name,p.desc,...p.tags.map(t=>kinds[t])].join(' ')).includes(q))}
function drawMap(){const list=filtered();$('#placeCount').textContent=list.length+' luoghi';$('#places').innerHTML=list.map(p=>`<article class="place"><span class="tag">${p.tags.slice(0,2).map(t=>kinds[t]).join(' · ')}</span><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><button class="secondary" data-add="${p.id}">＋ Nel programma</button></article>`).join('')||'<p>Nessun luogo per questa ricerca.</p>';$$('[data-add]').forEach(b=>b.onclick=()=>choosePlace(b.dataset.add));if(!window.L){$('#mapFallback').textContent='Mappa non disponibile. Tutti i luoghi restano accessibili nell’elenco.';return}if(!map){$('#mapCanvas').innerHTML='';map=L.map('mapCanvas').setView([41,17],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);layer=L.layerGroup().addTo(map)}layer.clearLayers();list.forEach(p=>{const included=allSteps().some(s=>s.id===p.id);const marker=L.marker([p.lat,p.lon],{icon:L.divIcon({className:'',html:`<div class="pin ${included?'inplan':''}">${included?'✓':'•'}</div>`,iconSize:[27,27]})}).addTo(layer);const box=document.createElement('div');box.innerHTML=`<strong>${esc(p.name)}</strong><br>${esc(p.desc)}<br>`;const b=document.createElement('button');b.textContent='Aggiungi al programma';b.className='secondary';b.onclick=()=>choosePlace(p.id);box.append(b);marker.bindPopup(box)});const coords=(state.plan[day]||[]).filter(p=>Number.isFinite(p.lat)).map(p=>[p.lat,p.lon]);if(coords.length>1)L.polyline(coords,{color:'#e94057',weight:3,dashArray:'6 8'}).addTo(layer);map.invalidateSize();if(list.length)map.fitBounds(L.latLngBounds(list.map(p=>[p.lat,p.lon])),{padding:[25,25],maxZoom:11})}
function choosePlace(id){const p=places.find(p=>p.id===id);dialog(p.name,`<p>${esc(p.desc)}</p><label>A quale giorno aggiungere?<select id="addDay">${Array.from({length:state.days},(_,i)=>`<option value="${i}" ${i===day?'selected':''}>${esc(dayLabel(i))}</option>`).join('')}</select></label><button class="primary" id="confirmAdd">Aggiungi questa tappa</button>`);$('#confirmAdd').onclick=()=>{day=Number($('#addDay').value);while(state.plan.length<state.days)state.plan.push([]);state.plan[day].push({...p,uid:uid(),time:''});save();$('#modal').close();drawMap();toast(p.name+' aggiunto al giorno '+(day+1))}}
function renderBudget(){const total=state.expenses.reduce((a,e)=>a+e.cents,0);$('#budgetSummary').innerHTML=`<div class="stat"><strong>${money(total)}</strong><span>Spese inserite</span></div><div class="stat"><strong>${money(Math.round(total/state.people))}</strong><span>Media / persona</span></div><div class="stat"><strong>${state.people}</strong><span>Nel gruppo</span></div>`;$('#members').value=state.members.join(', ');$('#payer').innerHTML=state.members.map(n=>`<option>${esc(n)}</option>`).join('');$('#beneficiaries').innerHTML=state.members.map((n,i)=>`<label class="check"><input type="checkbox" value="${i}" checked>${esc(n)}</label>`).join('');$('#expenseList').innerHTML=state.expenses.map(e=>`<article class="expense"><div><strong>${esc(e.title)}</strong><p>${esc(e.payer)} ha pagato · diviso tra ${e.who.length} persone</p><button class="textBtn" data-delete-exp="${e.id}">Elimina</button></div><strong>${money(e.cents)}</strong></article>`).join('');$$('[data-delete-exp]').forEach(b=>b.onclick=()=>{if(confirm('Eliminare questa spesa?')){state.expenses=state.expenses.filter(e=>e.id!==b.dataset.deleteExp);save();renderBudget()}});const transfers=settle();$('#settlements').innerHTML=transfers.length?transfers.map(t=>`<div class="settle"><b>${esc(t.from)}</b> rimborsa <b>${money(t.cents)}</b> a ${esc(t.to)}</div>`).join(''):'<p>Nessun rimborso previsto.</p>';$('#splitLink').value=state.splitLink;$('#openSplit').hidden=!state.splitLink;if(state.splitLink)$('#openSplit').href=state.splitLink}
function settle(){const balance=Object.fromEntries(state.members.map(n=>[n,0]));for(const e of state.expenses){balance[e.payer]+=e.cents;const each=Math.floor(e.cents/e.who.length),rest=e.cents%e.who.length;e.who.forEach((n,i)=>balance[n]-=each+(i<rest?1:0))}const debt=Object.entries(balance).filter(([,v])=>v<0).map(([n,v])=>({n,v:-v})),credit=Object.entries(balance).filter(([,v])=>v>0).map(([n,v])=>({n,v}));const out=[];let i=0,j=0;while(i<debt.length&&j<credit.length){const c=Math.min(debt[i].v,credit[j].v);out.push({from:debt[i].n,to:credit[j].n,cents:c});debt[i].v-=c;credit[j].v-=c;if(!debt[i].v)i++;if(!credit[j].v)j++}return out}
$('#saveMembers').onclick=()=>{const list=$('#members').value.split(',').map(x=>x.trim()).filter(Boolean);if(list.length!==state.people||new Set(list).size!==list.length||list.some(x=>x.length>60)){toast('Inserite esattamente '+state.people+' nomi diversi (massimo 60 caratteri).');return}if(state.expenses.length&&state.members.some((n,i)=>list[i]!==n)){toast('I nomi sono collegati alle spese. Eliminate o esportate le spese prima di rinominare il gruppo.');return}state.members=list;save();renderBudget();toast('Partecipanti salvati')};
$('#expenseForm').onsubmit=e=>{e.preventDefault();const who=$$('#beneficiaries input:checked').map(x=>state.members[Number(x.value)]);if(!who.length){toast('Scegliete almeno un beneficiario.');return}state.expenses.push({id:uid(),title:$('#expenseTitle').value.trim(),cents:Math.round(Number($('#amount').value)*100),payer:$('#payer').value,who});save();$('#expenseForm').reset();renderBudget();toast('Spesa aggiunta')};
function validSplit(link){try{const u=new URL(link);return u.protocol==='https:'&&['splitwise.com','tricount.com','tricount.page.link','tricount.app'].some(d=>u.hostname===d||u.hostname.endsWith('.'+d))}catch{return false}}
$('#saveSplit').onclick=()=>{let l=$('#splitLink').value.trim();if(l&&!validSplit(l)){toast('Usate un link HTTPS ufficiale di Splitwise o Tricount.');return}state.splitLink=l;save();renderBudget();toast('Link salvato')};
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),15000)}
$('#exportExpenses').onclick=()=>{const cell=v=>'"'+String(v).replace(/^[=+@-]/,"'"+'$&').replace(/"/g,'""')+'"';const rows=[['Spesa','Importo EUR','Pagato da','Beneficiari'],...state.expenses.map(e=>[e.title,(e.cents/100).toFixed(2),e.payer,e.who.join(' | ')])];download(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'aracne-depenses.csv')};
function renderNotes(){$('#noteDay').innerHTML='<option value="-1">Tutto il viaggio</option>'+Array.from({length:state.days},(_,i)=>`<option value="${i}">${esc(dayLabel(i))}</option>`).join('');$('#noteList').innerHTML=state.notes.map(n=>`<article class="noteCard"><div class="small">${n.privacy==='private'?'Personale':'Per il gruppo'} · ${n.day<0?'Tutto il viaggio':esc(dayLabel(n.day))}</div><div>${esc(n.text)}</div><div class="actions"><button class="textBtn" data-edit-note="${n.id}">Modifica</button><button class="textBtn" data-delete-note="${n.id}">Elimina</button></div></article>`).join('');$$('[data-delete-note]').forEach(b=>b.onclick=()=>{if(confirm('Eliminare questa nota?')){state.notes=state.notes.filter(n=>n.id!==b.dataset.deleteNote);save();renderNotes()}});$$('[data-edit-note]').forEach(b=>b.onclick=()=>{const n=state.notes.find(n=>n.id===b.dataset.editNote);dialog('Modifica la nota',`<form id="editNoteForm"><label>Nota<textarea id="editNote" rows="5" required maxlength="4000">${esc(n.text)}</textarea></label><label>Visibilità<select id="editPrivacy"><option value="private" ${n.privacy==='private'?'selected':''}>Personale</option><option value="group" ${n.privacy==='group'?'selected':''}>Per il gruppo</option></select></label><button class="primary">Salva</button></form>`);$('#editNoteForm').onsubmit=e=>{e.preventDefault();n.text=$('#editNote').value;n.privacy=$('#editPrivacy').value;save();$('#modal').close();renderNotes()}})}
$('#noteForm').onsubmit=e=>{e.preventDefault();state.notes.unshift({id:uid(),text:$('#noteText').value,day:Number($('#noteDay').value),privacy:$('#notePrivacy').value});save();$('#noteText').value='';renderNotes();toast('Nota salvata nel diario')};
function shareText(scope,includeNotes){const indexes=scope==='all'?Array.from({length:state.days},(_,i)=>i):[Number(scope)];let lines=[state.name,state.people+' persone · '+themes.find(t=>t[0]===state.theme)[2],''];for(const d of indexes){lines.push(dayLabel(d));const arr=state.plan[d]||[];arr.forEach(p=>lines.push((p.time?p.time+' · ':'')+p.name+(p.desc?' — '+p.desc:'')));if(!arr.length)lines.push('Programma libero');const route=arr.filter(p=>Number.isFinite(p.lat));if(state.transport==='transit'&&route.length>1)route.slice(1).forEach((p,i)=>lines.push('Collegamento '+(i+1)+' : '+mapsUrl([route[i],p])));else if(route.length)lines.push('Itinerario'+(route.length>5?' (prime 5 tappe)':'')+' : '+mapsUrl(route));lines.push('')}if(includeNotes){const notes=state.notes.filter(n=>n.privacy==='group'&&(n.day===-1||indexes.includes(n.day)));if(notes.length)lines.push('Note del gruppo',...notes.map(n=>'• '+n.text))}lines.push('Preparato con Il Volo d’Aracne · Puglia');return lines.join('\n')}
function shareDialog(){dialog('Condividi il viaggio',`<p>Inviate il programma completo o una sola giornata. Note personali e spese restano escluse.</p><label>Cosa condividere?<select id="shareScope"><option value="all">Tutto il programma</option>${Array.from({length:state.days},(_,i)=>`<option value="${i}">${esc(dayLabel(i))}</option>`).join('')}</select></label><label class="check"><input id="includeNotes" type="checkbox">Includi le note « Per il gruppo »</label><label>Anteprima<textarea id="sharePreview" rows="7" readonly></textarea></label><div class="actions"><a id="wa" class="primary" target="_blank" rel="noopener">WhatsApp</a><button id="nativeShare" class="secondary">Condividi…</button><button id="copyShare" class="textBtn">Copia il testo</button></div><p class="small">La condivisione invia una copia del programma, non uno spazio collaborativo sincronizzato.</p>`);const update=()=>{const t=shareText($('#shareScope').value,$('#includeNotes').checked);$('#sharePreview').value=t;$('#wa').href='https://wa.me/?text='+encodeURIComponent(t)};$('#shareScope').onchange=update;$('#includeNotes').onchange=update;update();$('#nativeShare').onclick=async()=>{try{if(navigator.share)await navigator.share({title:state.name,text:$('#sharePreview').value});else await copy($('#sharePreview').value)}catch(e){if(e.name!=='AbortError')toast('Condivisione non disponibile: copiate il testo o usate WhatsApp.')}};$('#copyShare').onclick=()=>copy($('#sharePreview').value)}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Testo copiato')}catch{toast('Selezionate il testo nell’anteprima per copiarlo.')}}
$('#shareTop').onclick=shareDialog;$('#sharePlan').onclick=shareDialog;
$('#export').onclick=()=>download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'aracne-voyage.json');
$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error();const candidate=validate(JSON.parse(await f.text()));if(!confirm('Sostituire la bozza locale con questa copia? Esportate prima la bozza se volete conservarla.'))return;state=candidate;day=0;weatherSequence++;weatherByZone={};$('#recommendations').hidden=true;save();fillForm();show('prepare');toast('Viaggio importato')}catch{toast('Questa copia non è valida o è troppo grande. Il vostro viaggio è conservato.')}finally{e.target.value=''}};
$('#storyPhoto').onchange=e=>{const f=e.target.files[0];if(f&&f.size>15e6){toast('Scegliete una foto inferiore a 15 MB.');return}photoFile=f;$('#photoStatus').textContent=f?'Foto scelta: '+f.name:''};
function wrapText(ctx,text,x,y,maxWidth,lineHeight,maxLines=5){let words=text.split(/\s+/),line='',lines=[];for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);lines.slice(0,maxLines).forEach((l,i)=>ctx.fillText(l+(i===maxLines-1&&lines.length>maxLines?'…':''),x,y+i*lineHeight));return y+Math.min(lines.length,maxLines)*lineHeight}
$('#createStory').onclick=async()=>{try{const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1920;const c=canvas.getContext('2d');const grad=c.createLinearGradient(0,0,1080,1920);grad.addColorStop(0,'#692676');grad.addColorStop(.55,'#e94057');grad.addColorStop(1,'#f27121');c.fillStyle=grad;c.fillRect(0,0,1080,1920);if(photoFile){const img=await createImageBitmap(photoFile);const s=Math.max(1080/img.width,1920/img.height);c.drawImage(img,(1080-img.width*s)/2,(1920-img.height*s)/2,img.width*s,img.height*s);img.close();c.fillStyle='#24132ca8';c.fillRect(0,0,1080,1920)}c.fillStyle='white';c.font='600 30px sans-serif';c.fillText('IL VOLO D’ARACNE',85,150);c.font='28px sans-serif';c.fillText('PUGLIA · INSIEME',85,205);c.font='700 72px sans-serif';let y=wrapText(c,state.name,85,440,900,85,3);c.font='32px sans-serif';c.fillText(state.people+' persone · '+dayLabel(day),85,y+35);y+=180;c.font='500 43px sans-serif';const arr=(state.plan[day]||[]).slice(0,3);if(!arr.length)c.fillText('I nostri ricordi iniziano qui.',85,y);arr.forEach((p,i)=>{y=wrapText(c,(i+1)+'. '+p.name,85,y,880,60,2)+32});if((state.plan[day]||[]).length>3){c.font='28px sans-serif';c.fillText('E altri momenti da scoprire…',85,y+20)}c.font='28px sans-serif';c.fillText('La nostra Puglia, a modo nostro.',85,1735);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();const url=URL.createObjectURL(blob);dialog('La vostra storia è pronta',`<img src="${url}" alt="Anteprima della storia"><div class="actions"><button class="primary" id="downloadStory">Scarica l’immagine</button><button class="secondary" id="shareStory">Condividi l’immagine</button></div><p class="small">Importate poi l’immagine su Instagram o Facebook. Nulla viene pubblicato automaticamente.</p>`);$('#downloadStory').onclick=()=>download(blob,'aracne-story.png');$('#shareStory').onclick=async()=>{const f=new File([blob],'aracne-story.png',{type:'image/png'});try{if(navigator.canShare?.({files:[f]}))await navigator.share({files:[f],title:state.name});else{download(blob,'aracne-story.png');toast('Immagine scaricata: aprite il social per importarla.')}}catch(e){if(e.name!=='AbortError')toast('Scaricate l’immagine per condividerla.')}};$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true})}catch{toast('Foto non leggibile. Provate un’immagine JPEG/PNG o create la storia senza foto.')}};
